-- Phase 2 of the SRT-side security work (FU-6): per-session SRT
-- encryption. Adds a column to record the AES passphrase the
-- api-server mints at session start.
--
-- The passphrase is:
--   - generated by `start_session` via `secrets.token_urlsafe(24)`
--     (~32 url-safe chars; comfortably inside libsrt's 10-79 char range)
--   - returned to the agent inside the SRT URL as `&passphrase=<X>&pbkeylen=32`
--   - simultaneously pushed to MediaMTX via the path-management HTTP
--     API as `srtPublishPassphrase` per per-session dynamic path
--   - deleted from MediaMTX when the session ends (and stays in the DB
--     as audit trail)
--
-- Nullable so the migration is cheap to apply and pre-existing rows
-- (whose sessions either ended or were short-lived) get NULL. New
-- sessions always populate the column. The api-server reads it via
-- the existing `load_session_by_streamid` / `check_session_admit`
-- helpers when it needs to know what MediaMTX expects for a session.
--
-- Storage is plain text on purpose: the row is already account-scoped
-- via RLS and the passphrase is short-lived (per-session, expires with
-- the row's `expires_at`). Encrypting at rest here would add ops
-- complexity (rotating master keys, asymmetric reads) without changing
-- the threat surface.

alter table stream_sessions
  add column if not exists srt_publish_passphrase text;
